--- Patient ---
  -- Generic resource index for most of searches
  CREATE INDEX IF NOT EXISTS patient_resource_idx ON Patient USING GIN (resource jsonb_path_ops);
  ---- Patient.birtheate
  CREATE INDEX IF NOT EXISTS "patient_birthdate_param_jsonpath_multirange" ON "patient" USING gist (
    (
      aidbox_extract_range (
        "patient".resource,
        CAST(ARRAY['$."birthDate"[*]'] AS _jsonpath)
      )
    ) multirange_ops
  );

  ---- Patient.name
  CREATE INDEX IF NOT EXISTS patient_name_param_knife_string_trgm ON patient USING gin ((aidbox_text_search(knife_extract_text(resource, '[["name","family"],["name","given"],["name","middle"],["name","text"],["name","prefix"],["name","suffix"]]'))) gin_trgm_ops);

  ---- Patient.address
  CREATE INDEX IF NOT EXISTS patient_address_param_knife_string_trgm ON patient USING gin ((aidbox_text_search(knife_extract_text(resource, '[["address","text"],["address","district"],["address","country"],["address","city"],["address","line"],["address","state"],["address","postalCode"]]'))) gin_trgm_ops);


